// Worker entry: loads Prisma's query-compiler wasm as a real Wasm module (Wrangler bundles it),
// then delegates everything to the OpenNext handler. See scripts/patch-prisma-workerd.mjs.
// @ts-ignore generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
// @ts-ignore .wasm imports are resolved by Wrangler
import queryCompilerWasm from "./node_modules/.prisma/client/query_compiler_bg.wasm";
// @ts-ignore extracted by scripts/patch-workerd-deps.mjs
import yogaWasm from "./node_modules/yoga-layout/dist/binaries/yoga.wasm";

const wasmGlobals = globalThis as unknown as { __PRISMA_QUERY_COMPILER_WASM: unknown; __YOGA_WASM_MODULE: unknown };
wasmGlobals.__PRISMA_QUERY_COMPILER_WASM = queryCompilerWasm;
wasmGlobals.__YOGA_WASM_MODULE = yogaWasm;

// exceljs pulls in graceful-fs, which calls process.umask() on load; the Workers polyfill throws
process.umask = () => 0o022;

export default {
  fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext) {
    return handler.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;
